let source = 'cron';
try {
  const tg = $('Telegram Trigger').first().json;
  if (tg && (tg.message || tg.callback_query)) source = 'telegram';
} catch (e) {
  source = 'cron';
}
const settings = items[0].json;
return [{ json: { ...settings, __source: source } }];

const settings = $('Настройки workflow').first().json;
const webOrigin = String(settings.webOrigin || 'https://avtovozom.com').replace(/\/$/, '');
const allowId = String(settings.operatorTelegramUserId || '').trim();
const token = String(settings.telegramBotToken || '').trim();

const raw = $('Telegram Trigger').first().json;
const cb = raw.callback_query || null;
const msg = (cb && cb.message) || raw.message || {};
const from = (cb && cb.from) || msg.from || {};
const chat = msg.chat || {};
const chatId = String(chat.id || '');
const userId = String(from.id || '');
const isPrivate = chat.type === 'private';
const allowed = isPrivate && (!allowId || allowId.includes('ВАШ') || userId === allowId);

let userText = String(msg.text || msg.caption || '').trim();
if (cb && cb.data) {
  const data = String(cb.data || '');
  if (data.startsWith('pub:')) userText = 'Опубликовать car_id=' + data.slice(4);
  else if (data.startsWith('skip:')) userText = 'Отклонить car_id=' + data.slice(5);
  else if (data.startsWith('swap:')) userText = 'Поменять авто. Текущий черновик car_id=' + data.slice(5) + '. Сделай release этого id (вернуть в очередь, НЕ skip). Выбери ДРУГОЙ лот: get_queue(exclude_ids=' + data.slice(5) + '), generate_text, send_draft.';
  else userText = data;
  if (token && !token.includes('REPLACE')) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.telegram.org/bot' + token + '/answerCallbackQuery',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ callback_query_id: cb.id }),
        json: false,
        ignoreHttpStatusErrors: true,
      });
    } catch (e) {}
  }
}
const reply = msg.reply_to_message;
if (reply) {
  const rt = String(reply.text || reply.caption || '').trim();
  if (rt) userText = 'Ответ на черновик:\n' + rt.slice(0, 800) + '\n\nСообщение оператора:\n' + userText;
}
const voice = (!cb && (msg.voice || msg.audio)) || null;
const doc = !cb ? msg.document : null;
const isAudioDoc = !!(doc && String(doc.mime_type || '').startsWith('audio/'));
const voiceFileId = String((voice && voice.file_id) || (isAudioDoc && doc.file_id) || '');
const hasVoice = Boolean(voiceFileId);

return [{
  json: {
    chatId,
    userId,
    username: from.username || '',
    firstName: from.first_name || '',
    userText,
    hasVoice,
    voiceFileId,
    llmModel: settings.llmModel || 'gpt-5.5',
    systemPrompt: String(settings.systemPrompt || '') + '\n\nСайт: ' + webOrigin,
    allowed,
    fromCron: false,
  }
}];

const settings = $('Настройки workflow').first().json;
const ctx = items[0].json;
const secret = String(settings.agentApiSecret || '').trim();
const base = String(settings.apiBaseUrl || '').replace(/\/$/, '');
const picks = Math.min(5, Math.max(1, Number(settings.picksPerRun || 1) || 1));
const shortlistLimit = Math.min(20, Math.max(5, Number(settings.shortlistLimit || 12) || 12));

async function agentRequest(method, path) {
  if (!secret || secret.includes('ЗАМЕНИТЕ')) {
    return { error: 'config', message: 'agentApiSecret не настроен', count: 0, items: [] };
  }
  if (!base) return { error: 'config', message: 'apiBaseUrl пуст', count: 0, items: [] };
  try {
    const resp = await this.helpers.httpRequest({
      method,
      url: base + path,
      headers: { 'Content-Type': 'application/json', 'X-Agent-Secret': secret },
      json: false,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 30000,
    });
    const status = resp.statusCode || resp.status || 0;
    const rawBody = resp.body ?? resp.data ?? '';
    const text = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);
    if (status < 200 || status >= 300) {
      return { error: 'HTTP ' + status, message: text.slice(0, 400), count: 0, items: [] };
    }
    try { return JSON.parse(text); } catch { return { error: 'parse', message: text.slice(0, 400), count: 0, items: [] }; }
  } catch (error) {
    return { error: 'http', message: String(error.message || error).slice(0, 400), count: 0, items: [] };
  }
}

function toTsv(items) {
  const header = 'id\tbrand\tmodel\tmodel_id\tyear\tmileage_km\thorsepower\testimated_total_rub\tis_popular\tphoto_count\turl';
  const lines = (items || []).map((r) => [
    r.id ?? '',
    r.brand ?? '',
    r.model ?? '',
    r.model_id ?? '',
    r.year ?? '',
    r.mileage_km ?? '',
    r.horsepower ?? '',
    r.estimated_total_rub ?? '',
    r.is_popular ? '1' : '0',
    r.photo_count ?? '',
    r.canonical_web_url ?? '',
  ].join('\t'));
  return [header, ...lines].join('\n');
}

const data = await agentRequest.call(this, 'GET', '/agent/v1/social/queue?limit=' + shortlistLimit + '&compact=1');
const itemsQueue = Array.isArray(data.items) ? data.items : [];
const models = [];
const seen = new Set();
for (const row of itemsQueue) {
  const key = String(row.model_id || row.brand + '|' + row.model);
  if (seen.has(key)) continue;
  seen.add(key);
  models.push(`${row.brand} ${row.model} (model_id=${row.model_id}, свежий лот id=${row.id})`);
}

const userText = [
  String(ctx.userText || '').trim(),
  '',
  'Шортлист собрал воркер БЕЗ ИИ (разные модели, popular, фото, свежесть). НЕ вызывай get_queue, get_car, get_memory. Выбери ' + picks + ' id из TSV → generate_text → send_draft. Не вызывай publish.',
  '',
  data.error ? ('Ошибка очереди: ' + (data.message || data.error)) : ('В очереди лотов: ' + (data.count ?? itemsQueue.length)),
  models.length ? ('Уникальные модели:\n- ' + models.join('\n- ')) : 'Уникальных моделей нет.',
  '',
  'Таблица:',
  toTsv(itemsQueue) || '(пусто)',
].join('\n');

return [{ json: { ...ctx, userText, queueCount: data.count ?? itemsQueue.length } }];

const raw = String(items[0].json.output ?? '').trim();
function dedupeReply(text) {
  if (!text) return text;
  const half = Math.floor(text.length / 2);
  if (text.length > 30) {
    const left = text.slice(0, half).trim();
    const right = text.slice(half).trim();
    if (left === right) return left;
  }
  const parts = text.split(/\n+/).map((p) => p.trim()).filter(Boolean);
  const unique = [];
  for (const p of parts) {
    if (unique[unique.length - 1] !== p) unique.push(p);
  }
  return unique.join('\n');
}
function escapeTelegramHtml(text) {
  return String(text || '')
    .replace(/\u0000/g, '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .trim();
}
return [{ json: { output: escapeTelegramHtml(dedupeReply(raw)) } }];

