const car = await agentRequest.call(this, 'GET', '/agent/v1/social/cars/' + carId);
if (car.error || car.detail === 'car not found') return JSON.stringify(car);
if (!text) text = String(car.last_draft_text || car.skeleton_text || '').trim();
if (!text) return JSON.stringify({ error: 'Пустой текст поста' });

const draft = await agentRequest.call(this, 'POST', '/agent/v1/social/draft', {
  car_id: carId,
  text,
  photo_ids: photoIds.length ? photoIds : undefined,
});
if (draft.error || draft.ok === false) return JSON.stringify(draft);

const chatId = String(settings.operatorChatId || '').trim();
const token = String(settings.telegramBotToken || '').trim();
if (!chatId || chatId.includes('ВАШ')) {
  return JSON.stringify({ ok: true, status: 'pending_review', warning: 'Черновик записан, но operatorChatId не задан — в Telegram не отправил' });
}
if (!token || token.includes('REPLACE')) {
  return JSON.stringify({ ok: true, status: 'pending_review', warning: 'Черновик записан, но telegramBotToken не задан — в Telegram не отправил' });
}

const photos = Array.isArray(car.photos) ? car.photos : [];
let urls = photos.map((p) => String(p.absolute_url || '').trim()).filter((u) => u.startsWith('http'));
if (photoIds.length) {
  const byId = new Map(photos.map((p) => [Number(p.id), String(p.absolute_url || '').trim()]));
  urls = photoIds.map((id) => byId.get(id)).filter((u) => u && u.startsWith('http'));
}
urls = urls.slice(0, 10);
const caption = text.length <= 1024 ? text : (text.slice(0, 1020) + '…');
const sent = { photos: 0, textFollowup: false };

async function tg(method, body) {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.telegram.org/bot' + token + '/' + method,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    json: false,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  const status = resp.statusCode || resp.status || 0;
  const rawBody = resp.body ?? resp.data ?? '';
  const raw = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);
  let parsed = {};
  try { parsed = JSON.parse(raw); } catch { parsed = { ok: false, description: raw.slice(0, 300) }; }
  if (status >= 300 || parsed.ok === false) {
    return { error: parsed.description || ('HTTP ' + status) };
  }
  return parsed;
}

if (urls.length >= 2) {
  const media = urls.map((u, i) => {
    const item = { type: 'photo', media: u };
    if (i === 0) item.caption = caption;
    return item;
  });
  const album = await tg.call(this, 'sendMediaGroup', { chat_id: chatId, media });
  if (album.error) return JSON.stringify({ ok: false, status: 'pending_review', error: 'Telegram album: ' + album.error });
  sent.photos = urls.length;
} else if (urls.length === 1) {
  const one = await tg.call(this, 'sendPhoto', { chat_id: chatId, photo: urls[0], caption });
  if (one.error) return JSON.stringify({ ok: false, status: 'pending_review', error: 'Telegram photo: ' + one.error });
  sent.photos = 1;
} else {
  const msg = await tg.call(this, 'sendMessage', { chat_id: chatId, text: caption });
  if (msg.error) return JSON.stringify({ ok: false, status: 'pending_review', error: 'Telegram text: ' + msg.error });
}
if (text.length > 1024) {
  await tg.call(this, 'sendMessage', { chat_id: chatId, text: text.slice(0, 4000) });
  sent.textFollowup = true;
}

const control = [
  'Черновик car_id=' + carId,
  (car.brand || '') + ' ' + (car.model || ''),
  '✅ опубликовать  ·  ❌ отклонить  ·  🔄 другое авто  ·  или напишите правки текста',
].join('\n');
await tg.call(this, 'sendMessage', {
  chat_id: chatId,
  text: control,
  reply_markup: {
    inline_keyboard: [[
      { text: '✅ Опубликовать', callback_data: 'pub:' + carId },
      { text: '❌ Отклонить', callback_data: 'skip:' + carId },
    ], [
      { text: '🔄 Другое авто', callback_data: 'swap:' + carId },
    ]],
  },
});

return JSON.stringify({ ok: true, status: 'pending_review', car_id: carId, sent });

